/** The report viewer's link guard. */
export const LINK_GUARD = "(function () {\n  document.addEventListener('click', function (event) {\n    var t = event.target;\n    var a = t && t.closest ? t.closest('a[href]') : null;\n    if (!a) return;\n    var href = a.getAttribute('href') || '';\n    if (href.charAt(0) === '#') return;\n    event.preventDefault();\n  }, true);\n})();";

/** The report viewer's zoom bridge. */
export const ZOOM_BRIDGE = "(function () {\n  function post(m) { parent.postMessage({ __dreamFrameZoom: m }, '*'); }\n  window.addEventListener('wheel', function (e) {\n    if ((e.ctrlKey || e.metaKey) && e.defaultPrevented) return;\n    if (e.ctrlKey || e.metaKey) e.preventDefault();\n    post({ kind: 'wheel', dx: e.deltaX, dy: e.deltaY, ctrl: !!(e.ctrlKey || e.metaKey), x: e.clientX, y: e.clientY });\n  }, { passive: false });\n  window.addEventListener('keydown', function (e) {\n    if (e.key === 'Escape') post({ kind: 'escape' });\n  });\n  window.addEventListener('dblclick', function (e) {\n    post({ kind: 'dblclick', x: e.clientX, y: e.clientY });\n  });\n  ['gesturestart', 'gesturechange', 'gestureend'].forEach(function (t) {\n    window.addEventListener(t, function (e) {\n      e.preventDefault();\n      post({ kind: 'gesture', phase: t.slice(7), scale: e.scale, x: e.clientX, y: e.clientY });\n    });\n  });\n})();";

/** pageDefaultCss(true): page defaults for a report that brings no styles. */
export const PAGE_DEFAULT_CSS_INSET = "\n:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body {\n  max-width: calc(72ch + 2 * var(--space-6));\n  margin-inline: auto;\n  padding: var(--space-6);\n  overflow-wrap: break-word;\n}\n:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body .dc-doc > * + :is(.dc-h1, .dc-h2, .dc-h3) { margin-top: var(--space-6); }\n:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body .dc-doc > :is(.dc-h1, .dc-h2, .dc-h3) + * { margin-top: var(--space-2); }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(h1, h2, h3, h4, h5, h6) {\n  margin: 1.5em 0 0.5em;\n  font-family: var(--font-family-display);\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  line-height: 1.3;\n  color: var(--color-text);\n}\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(h1) { font-size: 1.714rem; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(h2) { font-size: 1.286rem; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(h3) { font-size: 1.1rem; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(h4, h5, h6) { font-size: 1rem; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(p, ul, ol, dl, pre, table, blockquote, figure) { margin: 0 0 var(--space-3); }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(:is(h1, h2, h3, h4, h5, h6):not(:not(title, meta, link, base, script, style) ~ *)) { margin-top: 0; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(:last-child:is(p, ul, ol, dl, pre, table, blockquote, figure)) { margin-bottom: 0; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(ul, ol) { padding-inline-start: 1.5em; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(li + li) { margin-top: var(--space-1); }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(li > ul, li > ol) { margin: var(--space-1) 0 0; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(a) { color: var(--color-accent); }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(img, svg:not(.dc-graph-svg), video) { max-width: 100%; height: auto; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(hr) { margin: var(--space-6) 0; border: 0; border-top: 1px solid var(--color-border); }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(blockquote) {\n  padding-inline-start: var(--space-3);\n  border-inline-start: 2px solid var(--color-border-hover);\n  color: var(--color-text-secondary);\n}\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(code, pre) { font-family: var(--font-mono); font-size: 0.9em; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(pre) {\n  padding: var(--space-3);\n  overflow-x: auto;\n  background: var(--color-bg-secondary);\n  border-radius: var(--radius-md);\n}\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(table) { width: 100%; border-collapse: collapse; }\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(th, td) {\n  padding: var(--space-2) var(--space-3);\n  border-bottom: 1px solid var(--color-border);\n  text-align: start;\n}\n:where(:root:not([style]):not(:has(style:not([data-dc-host]), [style]:not(.dc-doc *))) body) :where(th) { font-weight: 600; color: var(--color-text-secondary); }\n";

export { SANDBOX_FONT_CSS };

export interface ServerSandboxSrcdocInput {
  html: string;
  css: string;
  tokens: Record<string, string>;
  scheme?: 'light' | 'dark';
  overrideCss?: string;
  headScript?: string;
}

function hostRootRule(tokens: Record<string, string>, scheme: 'light' | 'dark'): string {
  const rootVars = Object.entries(tokens).map(([token, value]) => `${token}: ${value};`).join(' ');
  return `:root { color-scheme: ${scheme}; ${rootVars} }`;
}

/** Mirror of the dashboard's `buildSandboxSrcdoc`: CSP meta FIRST, font, tokens, kit, override, head script, body. */
export function buildSandboxSrcdocServer(input: ServerSandboxSrcdocInput): string {
  const { html, css, tokens, scheme = 'light', overrideCss, headScript } = input;
  const parts = [
    '<!doctype html><html><head>',
    `<meta http-equiv="Content-Security-Policy" content="${SANDBOX_CSP}">`,
    '<meta charset="utf-8">',
    `<style ${HOST_STYLE_ATTR}>${SANDBOX_FONT_CSS}</style>`,
    `<style ${HOST_STYLE_ATTR}>${hostRootRule(tokens, scheme)}</style>`,
    `<style ${HOST_STYLE_ATTR}>${css}</style>`,
  ];
  if (overrideCss) parts.push(`<style ${HOST_STYLE_ATTR}>${overrideCss}</style>`);
  if (headScript) parts.push(`<script>${headScript}</script>`);
  parts.push('</head><body>', html);
  parts.push('</body></html>');
  return parts.join('\n');
}

export interface ServerChatSrcdocInput {
  html: string;
  tokens: Record<string, string>;
  scheme?: 'light' | 'dark';
  overrideCss?: string;
  mode?: 'card' | 'full';
  lang?: string;
}

/** Mirror of the dashboard's `buildChatSrcdoc`: a dream-html block as the chat draws it. */
export function buildChatSrcdocServer(input: ServerChatSrcdocInput): string {
  const { html, tokens, scheme = 'light', overrideCss, mode = 'card', lang } = input;
  const doc = buildSandboxSrcdocServer({
    html, css: CHAT_HTML_KIT_CSS, tokens, scheme, overrideCss,
    headScript: `${HEIGHT_BRIDGE}
${SELECTION_BRIDGE}
${REACH_BRIDGE}
${KIT_BEHAVIOUR}`,
  });
  const langAttr = lang ? ` lang="${lang.replace(/[^a-zA-Z0-9-]/g, '')}"` : '';
  return doc.replace('<!doctype html><html>', `<!doctype html><html${langAttr} data-dc-mode="${mode}">`);
}

/** Mirror of the dashboard's `buildReportSrcdoc`: a project HTML report page as the file viewer draws it. */
export function buildReportSrcdocServer(html: string, tokens: Record<string, string>, scheme: 'light' | 'dark' = 'light'): string {
  return buildSandboxSrcdocServer({
    html, css: CHAT_HTML_KIT_CSS, tokens, scheme, overrideCss: PAGE_DEFAULT_CSS_INSET,
    headScript: `${HEIGHT_BRIDGE}\n${SELECTION_BRIDGE}\n${LINK_GUARD}\n${ZOOM_BRIDGE}\n${KIT_BEHAVIOUR}`,
  });
}
